+/// #2865: three original parts demonstrate the five additional turning kinds.
+#[test]
+fn turning_cases_cover_five_additional_kinds() {
+    for (case, kinds) in [
+        ("bushing", &["BORING", "FORM TURNING"][..]),
+        ("contour-finishes", &["CHAMFERING", "MULTI-PASS TURNING"][..]),
